def execute(arguments):
    """
    文本模板渲染

    参数:
        arguments (dict): 包含以下字段
            - template (str): 模板文本，必填
            - variables (dict): 变量字典，用于替换模板中的占位符
            - delimiter (str): 变量分隔符，默认 "{{" 和 "}}"
            - default (str): 变量不存在时的默认值，默认空字符串

    返回:
        dict: 包含渲染结果的字典
            - success (bool): 是否成功
            - result (str): 渲染后的文本
            - variables_used (list): 使用的变量列表
            - error (str): 错误信息（失败时）

    模板语法:
        使用 {{variable_name}} 作为占位符
        支持嵌套属性: {{user.name}}
        支持默认值: {{variable|default_value}}
    """
    import re

    template = arguments.get("template", "")
    variables = arguments.get("variables", {})
    delimiter = arguments.get("delimiter", "{{")
    default = arguments.get("default", "")

    if not template:
        return {"success": False, "error": "请提供模板文本"}

    try:
        end_delimiter = "}}" if delimiter == "{{" else delimiter.replace("{", "}")
        pattern = re.escape(delimiter) + r"(.*??)" + re.escape(end_delimiter)

        variables_used = []

        def replace(match):
            expr = match.group(1).strip()
            variables_used.append(expr)

            if "|" in expr:
                var_name, default_val = expr.split("|", 1)
                var_name = var_name.strip()
                default_val = default_val.strip()
            else:
                var_name = expr
                default_val = default

            value = variables
            for key in var_name.split("."):
                if isinstance(value, dict):
                    value = value.get(key)
                else:
                    return default_val

            if value is None:
                return default_val

            return str(value)

        result = re.sub(pattern, replace, template)

        return {
            "success": True,
            "result": result,
            "variables_used": list(set(variables_used))
        }
    except Exception as e:
        return {"success": False, "error": f"渲染失败: {str(e)}"}
